const ALLOWED_PREFIXES = ['/customer'];

export function safeReturnUrl(value: string | null | undefined,
                              origin: string = window.location.origin): string | undefined {
  if (!value) return undefined;
  let url: URL;
  try {
    url = new URL(value, origin);    // relativ -> gegen eigene Origin, absolut bleibt absolut
  } catch {
    return undefined;                // kein gültiger Wert
  }
  if (url.origin !== origin) return undefined;   // //evil.example, https://…, javascript:
  const allowed = ALLOWED_PREFIXES.some(p =>
    url.pathname === p || url.pathname.startsWith(p + '/'));   // Pfad ist normalisiert
  return allowed ? url.pathname + url.search : undefined;
}
