import { ChangeDetectionStrategy, Component, computed, inject, input } from '@angular/core';
import { Customer } from '../customer.model';
import { CustomerStore } from '../customer.store';

@Component({                                       // (1) standalone, kein NgModule
  selector: 'customer-badge',
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (customer(); as c) {                       <!-- (2) Control Flow -->
      <span>{{ label() }}</span>
    }`,
})
export class CustomerBadgeComponent {
  customer = input<Customer>();                    // (3) Signal-Input, echter Typ
  private readonly store = inject(CustomerStore);  // (4) inject()
  label = computed(() =>                           // (5) immer aktuell
    `${this.customer()?.lastname} (${this.store.total()})`);
}

